import data from '@/data/matches.json'; import type { Match } from '@/types/match';
const matches = data as Match[];
export const getMatches = () => [...matches].sort((a,b)=>a.date.localeCompare(b.date));
export const getMatchById = (id:string) => matches.find(m=>m.matchId===id);
export const getMatchesBySeason = (season:number) => getMatches().filter(m=>m.season===season);
export const getLatestMatch = (season:number) => getMatchesBySeason(season).filter(m=>m.status==='FINISHED').at(-1);
export const getNextMatch = (season:number) => getMatchesBySeason(season).find(m=>m.status==='SCHEDULED');
